# Write conf/main.conf and conf/http.conf from the app's settings; nginx.conf
# includes them. nginx.conf, conf.d/ and the websites in sites/ are kept.
. (Join-Path $PSScriptRoot 'lib.ps1')
$state = Get-State

$bind = if ($env:BIND) { $env:BIND } else { '0.0.0.0' }
$port = if ($env:PORT) { $env:PORT } else { '8080' }
foreach ($d in 'conf', 'conf.d', 'sites', 'ssl', 'www', 'acme', 'logs', 'temp', 'run') {
    New-Item -ItemType Directory -Force -Path (Join-Path $AppDir $d) | Out-Null
}

Write-TextFile (Join-Path $AppDir 'conf\main.conf') @"
# Generated by XDeck from the app's settings; changes here are overwritten.
worker_processes 1;
error_log stderr warn;
"@

Write-TextFile (Join-Path $AppDir 'conf\http.conf') @"
# Generated by XDeck from the app's settings; changes here are overwritten.
access_log logs/access.log;
client_body_temp_path temp/client_body;
proxy_temp_path temp/proxy;
fastcgi_temp_path temp/fastcgi;
uwsgi_temp_path temp/uwsgi;
scgi_temp_path temp/scgi;

server {
    listen ${bind}:${port};
    server_name _;
    root html;
    index index.html;

    location / {
        try_files `$uri `$uri/ =404;
    }
}
"@

# Installations before 1.30-1 kept everything in conf\.
$old = Join-Path $AppDir 'conf\nginx.conf'
if (Test-Path $old) { Remove-Item -Force $old }

$prefix = (ConvertTo-SlashPath $AppDir) + '/'
Invoke-Native $state.exe @('-p', $prefix, '-c', 'nginx.conf', '-e', 'stderr', '-t')
